from typing import List, Tuple


def parse_input(input_text: str) -> Tuple[List[int], int]:
    """Parse the input text into nums and target."""
    lines = [line.strip() for line in input_text.strip().splitlines() if line.strip()]
    nums_line = lines[0]
    # Accept both "1,2,3" and "[1, 2, 3]" styles.
    if nums_line.startswith("[") and nums_line.endswith("]"):
        nums_line = nums_line[1:-1]
    nums = [int(part.strip()) for part in nums_line.split(",") if part.strip()]
    target = int(lines[1].strip())
    return nums, target


def solve(input_text: str) -> str:
    nums, target = parse_input(input_text)

    # One-pass hash map solution: for each value, check whether the
    # complement has already been seen.
    seen = {}
    for j, value in enumerate(nums):
        complement = target - value
        if complement in seen and seen[complement] != j:
            i = seen[complement]
            if i > j:
                i, j = j, i
            return f"{i}, {j}\n"
        seen[value] = j

    # The problem guarantees exactly one valid answer; this is a safety net.
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return f"{i}, {j}\n"

    raise ValueError("No valid pair found")

