def solve(input_text: str) -> str:
    data = list(map(int, input_text.split()))
    pos = 0
    n = data[pos]; pos += 1
    m = data[pos]; pos += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = data[pos]; v = data[pos + 1]; pos += 2
        adj[u].append(v)
        adj[v].append(u)

    removed = [False] * (n + 1)
    parent = [0] * (n + 1)
    size = [0] * (n + 1)

    # For each vertex store its centroid-ancestors and distances to them.
    anc_c = [[] for _ in range(n + 1)]
    anc_d = [[] for _ in range(n + 1)]

    sys.setrecursionlimit(1_000_000)

    def decompose(start):
        # Collect the current connected component (not containing removed vertices).
        order = []
        stack = [start]
        parent[start] = 0
        while stack:
            v = stack.pop()
            order.append(v)
            for to in adj[v]:
                if to != parent[v] and not removed[to]:
                    parent[to] = v
                    stack.append(to)

        total = len(order)

        # Subtree sizes inside this component (rooted at start).
        for v in reversed(order):
            s = 1
            for to in adj[v]:
                if to != parent[v] and not removed[to] and parent[to] == v:
                    s += size[to]
            size[v] = s

        # Find the centroid.
        c = start
        while True:
            heavy = 0
            for to in adj[c]:
                if to != parent[c] and not removed[to] and parent[to] == c and size[to] * 2 > total:
                    heavy = to
                    break
            if heavy == 0:
                break
            c = heavy

        removed[c] = True

        # Distances from centroid to all vertices of this component.
        parent[c] = 0
        stack = [(c, 0)]
        anc_c[c].append(c)
        anc_d[c].append(0)
        while stack:
            v, d = stack.pop()
            for to in adj[v]:
                if to != parent[v] and not removed[to]:
                    parent[to] = v
                    anc_c[to].append(c)
                    anc_d[to].append(d + 1)
                    stack.append((to, d + 1))

        # Recurse into the remaining components.
        for to in adj[c]:
            if not removed[to]:
                decompose(to)

    decompose(1)

    best = [10**9] * (n + 1)

    def add_red(v):
        for i in range(len(anc_c[v])):
            c = anc_c[v][i]
            d = anc_d[v][i]
            if d < best[c]:
                best[c] = d

    add_red(1)

    out = []
    for _ in range(m):
        t = data[pos]; v = data[pos + 1]; pos += 2
        if t == 1:
            add_red(v)
        else:
            ans = 10**9
            ac = anc_c[v]
            ad = anc_d[v]
            for i in range(len(ac)):
                val = best[ac[i]] + ad[i]
                if val < ans:
                    ans = val
            out.append(str(ans))

    return "\n".join(out)

