def solve(input_text: str) -> str:
    data = list(map(int, input_text.split()))
    if not data:
        return ""
    n, m = data[0], data[1]
    g = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(n - 1):
        u = data[idx]
        v = data[idx + 1]
        idx += 2
        g[u].append(v)
        g[v].append(u)

    removed = [False] * (n + 1)
    size = [0] * (n + 1)
    par = [0] * (n + 1)
    ancestors = [[] for _ in range(n + 1)]
    distances = [[] for _ in range(n + 1)]

    def get_order(start):
        order = []
        par[start] = 0
        stack = [start]
        while stack:
            u = stack.pop()
            order.append(u)
            pu = par[u]
            for w in g[u]:
                if w != pu and not removed[w]:
                    par[w] = u
                    stack.append(w)
        for u in reversed(order):
            s = 1
            pu = par[u]
            for w in g[u]:
                if w != pu and not removed[w]:
                    s += size[w]
            size[u] = s
        return order

    def decompose(start, pc):
        order = get_order(start)
        total = size[start]
        best_imbalance = total + 1
        cent = start
        for u in order:
            max_part = total - size[u]  # part towards the parent side
            pu = par[u]
            for w in g[u]:
                if w != pu and not removed[w]:
                    sw = size[w]
                    if sw > max_part:
                        max_part = sw
            if max_part < best_imbalance:
                best_imbalance = max_part
                cent = u

        removed[cent] = True
        ancestors[cent].append(cent)
        distances[cent].append(0)

        for nb in g[cent]:
            if not removed[nb]:
                stack = [(nb, cent, 1)]
                while stack:
                    u, p, d = stack.pop()
                    ancestors[u].append(cent)
                    distances[u].append(d)
                    for w in g[u]:
                        if w != p and not removed[w]:
                            stack.append((w, u, d + 1))

        for nb in g[cent]:
            if not removed[nb]:
                decompose(nb, cent)

    decompose(1, 0)

    ops = []
    for _ in range(m):
        t = data[idx]
        v = data[idx + 1]
        idx += 2
        ops.append((t, v))

    INF = 10 ** 9
    best = [INF] * (n + 1)

    # vertex 1 is initially red
    for c, d in zip(ancestors[1], distances[1]):
        if d < best[c]:
            best[c] = d

    out = []
    for t, v in ops:
        anc = ancestors[v]
        dst = distances[v]
        if t == 1:
            for c, d in zip(anc, dst):
                if d < best[c]:
                    best[c] = d
        else:
            ans = INF
            for c, d in zip(anc, dst):
                val = best[c] + d
                if val < ans:
                    ans = val
            out.append(str(ans))

    return "\n".join(out)


