def largest_rectangle_area(heights: List[int]) -> int:
    """Return the area of the largest rectangle in the histogram."""
    stack = []
    max_area = 0
    # Append a sentinel height 0 to flush all remaining bars from the stack.
    for i, h in enumerate(heights + [0]):
        start = i
        while stack and stack[-1][1] > h:
            idx, height = stack.pop()
            # width extends from idx to i-1
            width = i - idx
            area = height * width
            if area > max_area:
                max_area = area
            start = idx
        stack.append((start, h))
    return max_area


def solve(input_text: str) -> str:
    """Parse the input and return the largest rectangle area as a string."""
    text = input_text.strip()
    if not text:
        return ""
    if text.startswith("["):
        heights = json.loads(text)
    elif text.startswith("heights"):
        # fallback: parse "heights = [...]"
        heights = json.loads(text.split("=", 1)[1].strip())
    else:
        heights = json.loads(text)
    return str(largest_rectangle_area(heights))

