def find_median(nums1, nums2):
    # Binary search over the smaller array for O(log(m+n)) time.
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    m, n = len(nums1), len(nums2)
    total = m + n
    half = total // 2

    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2      # elements taken from nums1 (left partition)
        j = half - i            # elements taken from nums2 (left partition)

        left1 = nums1[i - 1] if i > 0 else float('-inf')
        right1 = nums1[i] if i < m else float('inf')
        left2 = nums2[j - 1] if j > 0 else float('-inf')
        right2 = nums2[j] if j < n else float('inf')

        if left1 <= right2 and left2 <= right1:
            if total % 2 == 1:
                return float(min(right1, right2))
            return (max(left1, left2) + min(right1, right2)) / 2.0
        elif left1 > right2:
            hi = i - 1
        else:
            lo = i + 1


def solve(input_text: str) -> str:
    data = json.loads(input_text)
    median = find_median(data["nums1"], data["nums2"])
    return str(median)

