class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(values):
    """Build a binary tree from LeetCode level-order list representation."""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = [root]
    idx = 1
    while queue and idx < len(values):
        node = queue.pop(0)
        if idx < len(values):
            val = values[idx]
            idx += 1
            if val is not None:
                node.left = TreeNode(val)
                queue.append(node.left)
        if idx < len(values):
            val = values[idx]
            idx += 1
            if val is not None:
                node.right = TreeNode(val)
                queue.append(node.right)
    return root


def solve(input_text: str) -> str:
    data = json.loads(input_text)
    root = build_tree(data["root"])
    if root is None:
        return "0"

    best = float("-inf")
    gains = {}
    # Iterative post-order traversal to avoid recursion-depth issues on long chains.
    stack = [(root, False)]
    while stack:
        node, visited = stack.pop()
        if node is None:
            continue
        if visited:
            left_gain = max(gains.get(id(node.left), 0), 0)
            right_gain = max(gains.get(id(node.right), 0), 0)
            through = node.val + left_gain + right_gain
            if through > best:
                best = through
            gains[id(node)] = node.val + max(left_gain, right_gain)
        else:
            stack.append((node, True))
            if node.right is not None:
                stack.append((node.right, False))
            if node.left is not None:
                stack.append((node.left, False))

    return str(best)

