def merge_k_sorted_lists(lists):
    """Merge a list of sorted integer lists into one sorted list."""
    heap = []
    for i, lst in enumerate(lists):
        if lst:
            # push (value, list index, element index)
            heapq.heappush(heap, (lst[0], i, 0))

    result = []
    while heap:
        value, list_idx, elem_idx = heapq.heappop(heap)
        result.append(value)
        lst = lists[list_idx]
        nxt = elem_idx + 1
        if nxt < len(lst):
            heapq.heappush(heap, (lst[nxt], list_idx, nxt))
    return result


def solve(input_text: str) -> str:
    data = json.loads(input_text)
    # data is a list of lists (possibly empty list of lists)
    merged = merge_k_sorted_lists(data)
    return str(merged)

