from collections import deque


def max_sliding_window(nums, k):
    """Return the maximum of each sliding window of size k."""
    result = []
    dq = deque()  # stores indices; values are decreasing from left to right
    for i, num in enumerate(nums):
        # Remove indices outside the current window
        while dq and dq[0] <= i - k:
            dq.popleft()
        # Maintain decreasing order: pop smaller values at the back
        while dq and nums[dq[-1]] <= num:
            dq.pop()
        dq.append(i)
        # The window is fully formed starting at index k - 1
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result


def solve(input_text: str) -> str:
    data = json.loads(input_text)
    nums = data["nums"]
    k = data["k"]
    return str(max_sliding_window(nums, k))

