def find_anagrams(s: str, p: str) -> list:
    n, m = len(s), len(p)
    if m > n:
        return []
    p_count = Counter(p)
    window_count = Counter(s[:m])
    result = []

    if window_count == p_count:
        result.append(0)

    for i in range(1, n - m + 1):
        removed = s[i - 1]
        added = s[i + m - 1]
        window_count[removed] -= 1
        if window_count[removed] == 0:
            del window_count[removed]
        window_count[added] += 1
        if window_count == p_count:
            result.append(i)

    return result

from typing import List


def find_anagrams(s: str, p: str) -> List[int]:
    ns, np = len(s), len(p)
    if np > ns:
        return []

    target = [0] * 26
    window = [0] * 26
    a = ord('a')

    for ch in p:
        target[ord(ch) - a] += 1
    for i in range(np):
        window[ord(s[i]) - a] += 1

    result = []
    if window == target:
        result.append(0)

    for i in range(np, ns):
        window[ord(s[i - np]) - a] -= 1
        window[ord(s[i]) - a] += 1
        if window == target:
            result.append(i - np + 1)

    return result


