def solve(input_text: str) -> str:
    data = input_text.split()
    if not data:
        return ""
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    dp = [0] * (m + 1)

    for _ in range(n):
        v = int(data[idx]); w = int(data[idx + 1]); s = int(data[idx + 2])
        idx += 3

        if v <= 0:
            # Items with zero volume are not expected by the statement,
            # but handle them safely: take all of them.
            if s > 0:
                for j in range(m + 1):
                    dp[j] += s * w
            continue
        if v > m:
            continue  # cannot fit even a single copy

        for r in range(v):
            # Positions r, r+v, r+2v, ... form one independent chain.
            # For position r + k*v, we may use t previous copies plus (k-t)
            # new copies, with 0 <= k - t <= s.
            maxk = (m - r) // v
            q = deque()  # stores (index t, value dp[r + t*v] - t*w), decreasing values
            old = dp  # snapshot of the dp before this item (we only read old values)

            for k in range(maxk + 1):
                key = old[r + k * v] - k * w
                while q and q[-1][1] <= key:
                    q.pop()
                q.append((k, key))
                # Only indices t >= k - s may contribute
                while q and q[0][0] < k - s:
                    q.popleft()
                dp[r + k * v] = q[0][1] + k * w

    return str(dp[m])

