        row_masks.append(masks)

    NEG = float('-inf')
    # dp maps (mask_row_r_minus_2, mask_row_r_minus_1) -> max cannons so far
    dp = {(0, 0): 0}

    for r in range(n):
        new_dp = {}
        for (m2, m1), val in dp.items():
            for mask in row_masks[r]:
                # vertical constraint: can't share a column with the two
                # immediately preceding rows
                if mask & m1 or mask & m2:
                    continue
                nv = val + bin(mask).count('1')
