def count_tilings(rows, cols):
    """Number of ways to tile a rows x cols board with 1x2 dominoes."""
    # transitions[cur] = all possible next-column masks
    # cur bit i = 1 means row i is already filled by a domino from the previous column.
    trans = [[] for _ in range(1 << rows)]
    for cur in range(1 << rows):
        def dfs(r, next_mask):
            if r == rows:
                trans[cur].append(next_mask)
                return
            if (cur >> r) & 1:
                dfs(r + 1, next_mask)
            else:
                # Place a horizontal domino extending into the next column.
                dfs(r + 1, next_mask | (1 << r))
                # Place a vertical domino (occupies rows r and r+1 in this column).
                if r + 1 < rows and not ((cur >> (r + 1)) & 1):
                    dfs(r + 2, next_mask)
        dfs(0, 0)

    dp = [0] * (1 << rows)
    dp[0] = 1
    for _ in range(cols):
        ndp = [0] * (1 << rows)
        for cur in range(1 << rows):
            if dp[cur] == 0:
                continue
            for nxt in trans[cur]:
                ndp[nxt] += dp[cur]
        dp = ndp
    return dp[0]


